solutions.naive:
class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        vals = []
        for row in matrix:
            for x in row:
                vals.append(x)
        vals.sort()
        return vals[k - 1]

solutions.better:
class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        import heapq
        n = len(matrix)
        heap = []
        for r in range(n):
            heapq.heappush(heap, (matrix[r][0], r, 0))
        ans = 0
        for _ in range(k):
            ans, r, c = heapq.heappop(heap)
            if c + 1 < n:
                heapq.heappush(heap, (matrix[r][c + 1], r, c + 1))
        return ans

solutions.optimal:
class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        n = len(matrix)
        lo, hi = matrix[0][0], matrix[-1][-1]
        while lo < hi:
            mid = (lo + hi) // 2
            count = 0
            r, c = n - 1, 0
            while r >= 0 and c < n:
                if matrix[r][c] <= mid:
                    count += r + 1
                    c += 1
                else:
                    r -= 1
            if count >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

